function day2StreetStageHtml() {
  const form = state.questPack?.storyForm5 || state.storyForm5;
  const day = state.save.dayIndex || 1;
  if (!form || day < 2) return "";
  const props = form.day2StreetStageProps || {};
  const pick = storyFlag("cold_open_mediate") ? props.mediate
    : storyFlag("cold_open_instigate") ? props.instigate
    : storyFlag("cold_open_stage") ? props.stage : null;
  if (!pick) return "";
  return (state.locale === "tr" && pick.htmlTr) ? pick.htmlTr : pick.html;
}

function mutateHotspotHtml(n, baseBtnHtml) {
  const form = state.questPack?.storyForm5 || state.storyForm5;
  const muts = form?.hotspotMutations || {};
  const mut = Object.values(muts).find(m =>
    (m.when?.dayIndexMin || 2) <= (state.save.dayIndex||1) &&
    (m.when?.flagsAll||[]).every(f => storyFlag(f)) &&
    (m.neighborId === n.id || m.alsoNeighborId === n.id)
  );
  if (!mut) return baseBtnHtml;
  const bubble = mut.neighborId === n.id ? mut.speechBubble
    : mut.alsoNeighborId === n.id ? mut.alsoSpeechBubble : null;
  const cls = mut.neighborId === n.id ? (mut.addClass||[]) : (mut.alsoAddClass||[]);
  const tid = mut.neighborId === n.id ? mut.testId : "";
  const bub = bubble ? `<span class="rp-hotspot__bubble" ${tid?`data-testid="${tid}"`:""}>${loc(bubble)}</span>` : "";
  return baseBtnHtml.replace('class="rp-hotspot', `class="rp-hotspot ${cls.join(" ")}`).replace("</button>", `${bub}</button>`);
}

